<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/OperatingFinanceService.php';
function finance_check(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);echo "OK: $message\n";}
$pdo=new PDO('sqlite::memory:');$pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);
$pdo->exec(file_get_contents(dirname(__DIR__).'/database/migrations/031-costs-cancellation-requests.sqlite.sql'));
$pdo->exec("CREATE TABLE destinations(id INTEGER PRIMARY KEY);INSERT INTO destinations VALUES(1);CREATE TABLE accounts(id INTEGER PRIMARY KEY,status TEXT);INSERT INTO accounts VALUES(1,'active'),(2,'active');CREATE TABLE business_account_memberships(account_id INTEGER,business_id INTEGER,status TEXT);INSERT INTO business_account_memberships VALUES(1,10,'active');CREATE TABLE business_subscriptions(id INTEGER PRIMARY KEY,business_id INTEGER,plan_code TEXT,status TEXT,starts_at TEXT,ends_at TEXT);INSERT INTO business_subscriptions VALUES(100,10,'page','active','2020-01-01',NULL)");
$service=new OperatingFinanceService($pdo);$day=gmdate('Y-m-d');$expense=['cost_date'=>$day,'category'=>'hosting','amount_cop'=>'12500.50','destination_id'=>'1','description'=>'Infraestructura de prueba'];$service->addCost($expense,'test-admin');
$summary=$service->summary($day,(new DateTimeImmutable($day))->modify('+1 day')->format('Y-m-d'));finance_check($summary['cost_count']===1&&$summary['costs_cop']===12500.5,'Real dated expenses sum into the chosen period');
foreach([['amount_cop'=>'-5'],['amount_cop'=>'12.500,50'],['cost_date'=>'2026-02-31'],['cost_date'=>'2999-01-01'],['destination_id'=>'99']] as $invalid){$rejected=false;try{$service->addCost(array_replace($expense,$invalid),'test');}catch(Throwable){$rejected=true;}finance_check($rejected,'Reject malformed cost '.json_encode($invalid));}
$service->voidCost(1,'Registro de prueba duplicado');finance_check($service->summary($day,'2999-01-01')['cost_count']===0,'Voiding removes expense from totals and preserves original');finance_check((int)$pdo->query('SELECT COUNT(*) FROM operating_costs')->fetchColumn()===1,'Original expense remains auditable');
$rejected=false;try{$service->requestCancellation(2,10,'price','');}catch(Throwable){$rejected=true;}finance_check($rejected,'Unrelated account cannot request cancellation');
$service->requestCancellation(1,10,'price','Precio fuera del presupuesto');$service->requestCancellation(1,10,'price','Retry');finance_check((int)$pdo->query('SELECT COUNT(*) FROM subscription_cancellation_requests')->fetchColumn()===1,'Retry does not duplicate cancellation request');finance_check($pdo->query('SELECT status FROM business_subscriptions')->fetchColumn()==='active','Request preserves already paid subscription');$service->reviewCancellation(1,'Se atendió la solicitud de no renovación.');finance_check($pdo->query('SELECT status FROM subscription_cancellation_requests')->fetchColumn()==='reviewed','Review is recorded separately from actual subscription status');
